// silent-failure vector. For each skill in cfg.Skills, it checks whether the
// skill is a curated built-in OR is returned by the agent's SkillDiscoverer.
// If any skill is neither, it returns a user-facing error. Empty Skills
// (prompt-only config) short-circuit to nil.
func verifyConfiguredSkillsInstalled(ctx context.Context, ag agent.Agent, cfg settings.ReviewConfig) error {
	if len(cfg.Skills) == 0 {
		return nil
	}

	builtins := builtinNameSet(skilldiscovery.CuratedBuiltinsFor(string(ag.Name())))

	discoveredNames := map[string]struct{}{}
	if d, ok := ag.(agent.SkillDiscoverer); ok {
