// computeEligibleConfigured returns agents that are (a) configured with a
// non-zero ReviewConfig and (b) have hooks installed, sorted alphabetically
// by name. Each entry's Label is the picker-visible string derived from
// the ReviewConfig.
func computeEligibleConfigured(ctx context.Context, s *settings.EntireSettings) []agentChoice {
	if s == nil {
		return nil
	}
	installed := GetAgentsWithHooksInstalled(ctx)
	installedSet := make(map[types.AgentName]struct{}, len(installed))
	for _, name := range installed {
		installedSet[name] = struct{}{}
	}
	var out []agentChoice
	for name, cfg := range s.Review {
		if cfg.IsZero() {
			continue
		}
		if _, ok := installedSet[types.AgentName(name)]; !ok {
			continue
		}
		out = append(out, agentChoice{Name: name, Label: labelForAgentChoice(name, cfg)})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

// labelForAgentChoice renders the picker label for one agent.
func labelForAgentChoice(name string, cfg settings.ReviewConfig) string {
	switch {
	case len(cfg.Skills) > 0:
		return fmt.Sprintf("%s   (%d skills configured)", name, len(cfg.Skills))
	case cfg.Prompt != "":
		return fmt.Sprintf("%s   (prompt-only)", name)
	default:
		// cfg.IsZero() callers already filter this case out; defensive.
		return name
	}
}

// promptForAgent runs a single-select huh picker over the given eligible
// agents and returns the picked name. Uses NewAccessibleForm so the form
// respects ACCESSIBLE=1 per CLAUDE.md.
func promptForAgent(ctx context.Context, eligible []agentChoice) (string, error) {
	_ = ctx
	if len(eligible) == 0 {
		return "", errors.New("no eligible agents to prompt for")
	}
	options := make([]huh.Option[string], 0, len(eligible))
	for _, c := range eligible {
		options = append(options, huh.NewOption(c.Label, c.Name))
	}
	// Default selection = alphabetically first, matching the pre-2.1
	// silent-default behavior so Enter-through users land on the same
	// agent they did before.
	picked := eligible[0].Name
	form := NewAccessibleForm(huh.NewGroup(
		huh.NewSelect[string]().
			Title("Which agent should run this review?").
			Options(options...).
			Value(&picked),
	))
	if err := form.Run(); err != nil {
		return "", fmt.Errorf("agent picker: %w", err)
	}
	return picked, nil
}
```

