	},
	"codex":      {{Name: "/review", Desc: "Review current changes and find issues"}},
	"gemini-cli": {},
}

// curatedBuiltinsFor returns the curated built-in list for agentName, or an
// empty slice if the agent is unknown. Callers must treat the return value
// as read-only.
