func TestClaudeCodeAgent_LaunchHeadlessCmd(t *testing.T) {
	t.Parallel()
	a := &claudecode.ClaudeCodeAgent{}
	cmd, err := a.LaunchHeadlessCmd(context.Background(), "review please")
