func adoptPendingReviewMarkerInto(ctx context.Context, s session.State, agentName types.AgentName) (session.State, bool, error) {
	m, ok, err := ReadPendingReviewMarker(ctx)
	if err != nil || !ok {
		return s, false, err
	}

	// Existing worktree-path guard (applies to all branches).
	if m.WorktreePath != "" && filepath.Clean(m.WorktreePath) != filepath.Clean(s.WorktreePath) {
		return s, false, nil // leave marker for the right worktree's session
	}

	// Existing SHA-drift guard (applies to all branches).
	currentSHA, shaErr := currentHeadSHA()
	if shaErr == nil && m.StartingSHA != "" && m.StartingSHA != currentSHA {
		_ = ClearPendingReviewMarker(ctx) // stale, clear it
		return s, false, nil
	}

	switch {
	case m.AgentName != "":
		// Phase 1 / 2.1 single-agent path — unchanged.
		if m.AgentName != string(agentName) {
			return s, false, nil
		}
		s.Kind = session.KindAgentReview
		s.ReviewSkills = m.Skills
		s.ReviewPrompt = m.Prompt
		_ = ClearPendingReviewMarker(ctx)
		return s, true, nil

	case len(m.AgentNames) > 0:
		// NEW multi-agent path.
		inList := false
		for _, n := range m.AgentNames {
			if n == string(agentName) {
				inList = true
				break
			}
		}
		if !inList {
			return s, false, nil
		}
		s.Kind = session.KindAgentReview
		s.ReviewSkills = m.Skills
		s.ReviewPrompt = m.Prompt
		// DO NOT clear marker — orchestrator owns that.
		return s, true, nil

	default:
		return s, false, nil // no adoption criteria
	}
}
