```go
package cli

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"os/signal"
	"path/filepath"
	"sync"
	"syscall"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/logging"
)

// Rate limiting: max ~10 preview messages per second per agent.
const previewRateWindow = 100 * time.Millisecond

// multiReviewOrchestrator owns the lifecycle of an N-agent parallel review:
// writes the shared pending marker, spawns goroutines per agent, drives
// cancellation, cleans up on exit. The TUI (Chunk 4) is separate — this
// orchestrator signals state changes via an output channel the TUI consumes.
//
// Chunk 3 implements the logic with io.Writer-based output dump; Chunk 4
// swaps in the tea.Program. See the spec's §Runtime orchestration for the
// full message shape.
type multiReviewOrchestrator struct {
	worktreePath string
	// tea-program hook for Chunk 4; nil here in Chunk 3 means "dump
	// directly to out at end".
	teaProgram interface {
		Send(msg interface{})
		Run() (interface{}, error)
	}
}

func newMultiReviewOrchestrator(worktreePath string) *multiReviewOrchestrator {
	return &multiReviewOrchestrator{worktreePath: worktreePath}
}

// Run spawns all tasks, waits for completion or cancellation, cleans up the
// marker, and dumps final per-agent responses to out.
func (o *multiReviewOrchestrator) Run(ctx context.Context, tasks []MultiAgentTask, out io.Writer) (MultiRunResult, error) {
	if len(tasks) == 0 {
		return MultiRunResult{}, errors.New("orchestrator: no tasks")
	}

	// 1. Write shared marker.
	headSHA, _ := currentHeadSHA() // best-effort
	agentNames := make([]string, len(tasks))
	for i, t := range tasks {
		agentNames[i] = t.Name
	}
	if err := WritePendingReviewMarker(ctx, PendingReviewMarker{
		AgentNames:   agentNames,
		Skills:       nil, // per-agent Skills are on their own Config; marker is informational
		Prompt:       "", // per-agent
		StartingSHA:  headSHA,
		StartedAt:    time.Now(),
		WorktreePath: o.worktreePath,
	}); err != nil {
		return MultiRunResult{}, fmt.Errorf("write marker: %w", err)
	}

	// 2. Defer marker cleanup — regardless of exit path.
	defer func() {
		if err := ClearPendingReviewMarker(context.Background()); err != nil {
			logging.Debug(ctx, "orchestrator: marker cleanup failed", "err", err.Error())
		}
	}()

	// 3. Cancel-aware context for the signal cascade.
	runCtx, cancelRun := context.WithCancel(ctx)
	defer cancelRun()

	// 4. Signal handler for Ctrl+C cascade (SIGTERM → 5s watchdog → SIGKILL).
	sigCh := make(chan os.Signal, 2)
	signal.Notify(sigCh, syscall.SIGINT)
	defer signal.Stop(sigCh)

	cancelled := &atomicBool{}
	go func() {
		select {
		case <-sigCh:
			cancelled.store(true)
			cancelRun() // SIGTERM to subprocesses via exec.CommandContext
			watchdog := time.NewTimer(5 * time.Second)
			defer watchdog.Stop()
			select {
			case <-sigCh:
				// Second Ctrl+C — immediate SIGKILL below via process.Kill
				forceKillAll(tasksCmds)
			case <-watchdog.C:
				// First-press window expired — SIGKILL.
				forceKillAll(tasksCmds)
			case <-runCtx.Done():
				// All done naturally.
			}
		case <-runCtx.Done():
		}
	}()

	// 5. Spawn one goroutine per task. Capture *exec.Cmd pointers for
	// the watchdog's SIGKILL escalation.
	tasksCmds := make([]*exec.Cmd, len(tasks))
	var wg sync.WaitGroup
	results := make([]AgentRunResult, len(tasks))

	for i, task := range tasks {
		i, task := i, task // capture
		wg.Add(1)
		go func() {
			defer wg.Done()
			startTime := time.Now()

			cmd, err := task.Agent.LaunchHeadlessCmd(runCtx, task.Prompt)
			if err != nil {
				results[i] = AgentRunResult{
					Name:     task.Name,
					Status:   AgentRunFailed,
					Duration: time.Since(startTime),
					Err:      fmt.Errorf("launch %s: %w", task.Name, err),
				}
				return
			}
			tasksCmds[i] = cmd

			var buf bytes.Buffer
			// Preview tee: line-oriented, rate-limited. Chunk 4 wires this
			// to the TUI; Chunk 3 only buffers for the final dump.
			cmd.Stdout = &buf
			cmd.Stderr = &buf

			runErr := cmd.Run()
			duration := time.Since(startTime)

			status := AgentRunDone
			exitCode := 0
			if runErr != nil {
				if exitErr, ok := runErr.(*exec.ExitError); ok {
					exitCode = exitErr.ExitCode()
					status = AgentRunFailed
				} else if errors.Is(runCtx.Err(), context.Canceled) {
					status = AgentRunCancelled
				} else {
					status = AgentRunFailed
				}
			}

			// Resolve transcript path + token usage post-exit.
			var transcriptPath string
			var tokenUsage *agent.TokenUsage
			if status == AgentRunDone {
				if sbp, ok := task.Agent.(agent.SessionBaseDirProvider); ok {
					dir, _ := sbp.GetSessionBaseDir()
					transcriptPath = resolveLatestTranscript(dir) // best-effort
					if transcriptPath != "" {
						data, err := os.ReadFile(transcriptPath) //nolint:gosec // derived from agent's own dir
						if err == nil {
							tokenUsage, _ = task.Agent.CalculateTokenUsage(data, 0)
						}
					}
				}
			}

			results[i] = AgentRunResult{
				Name:           task.Name,
				Status:         status,
				ExitCode:       exitCode,
				Duration:       duration,
				FinalOutput:    buf.Bytes(),
				Err:            runErr,
				TokenUsage:     tokenUsage,
				TranscriptPath: transcriptPath,
			}
		}()
	}

	wg.Wait()

	// 6. Dump per-agent final outputs.
	dumpMultiAgentResults(out, tasks, results, cancelled.load())

	return MultiRunResult{
		Runs:      results,
		Duration:  computeTotalDuration(results),
		Cancelled: cancelled.load(),
	}, nil
}

// dumpMultiAgentResults prints per-agent headers + FinalOutput, then a
// summary line, then transcript paths for successful agents.
func dumpMultiAgentResults(out io.Writer, tasks []MultiAgentTask, results []AgentRunResult, cancelled bool) {
	for i, r := range results {
		fmt.Fprintf(out, "\n─────── %s review ───────\n", tasks[i].Name)
		switch r.Status {
		case AgentRunFailed:
			fmt.Fprintf(out, "(failed — exit %d)\n", r.ExitCode)
			if r.Err != nil {
				fmt.Fprintf(out, "%v\n\n", r.Err)
			}
		case AgentRunCancelled:
			fmt.Fprintln(out, "(cancelled)\n")
		}
		out.Write(r.FinalOutput)
	}

	// Summary line.
	var nSucc, nFail, nCancel int
	for _, r := range results {
		switch r.Status {
		case AgentRunDone:
			nSucc++
		case AgentRunFailed:
			nFail++
		case AgentRunCancelled:
			nCancel++
		}
	}
	fmt.Fprintln(out)
	fmt.Fprintf(out, "✓ %d agents done in %s (%d succeeded, %d failed, %d cancelled)\n",
		len(results), computeTotalDuration(results), nSucc, nFail, nCancel)
	if !cancelled && nSucc > 0 {
		fmt.Fprintln(out, "  Run `git commit` to attach the review to the next checkpoint.")
	}

	// Transcript paths (where known).
	anyPath := false
	for _, r := range results {
		if r.TranscriptPath != "" {
			if !anyPath {
				fmt.Fprintln(out, "\n  Full transcripts (including tool calls + reasoning):")
				anyPath = true
			}
			fmt.Fprintf(out, "    %-12s → %s\n", r.Name, r.TranscriptPath)
		}
	}
}

func computeTotalDuration(results []AgentRunResult) time.Duration {
	var max time.Duration
	for _, r := range results {
		if r.Duration > max {
			max = r.Duration
		}
	}
	return max
}

func forceKillAll(cmds []*exec.Cmd) {
	for _, cmd := range cmds {
		if cmd == nil || cmd.Process == nil {
			continue
		}
		_ = cmd.Process.Kill()
	}
}

func resolveLatestTranscript(baseDir string) string {
	if baseDir == "" {
		return ""
	}
	entries, err := os.ReadDir(baseDir)
	if err != nil {
		return ""
	}
	// Best-effort: find newest .jsonl file in baseDir recursively. Could
	// also use agent.ResolveSessionFile if available. For Chunk 3 a simple
	// newest-file approach is sufficient; tests use a known fixture path.
	_ = entries
	return "" // Chunk 4 can refine; Chunk 3 leaves transcripts unresolved if ambiguous
}

type atomicBool struct {
	mu sync.Mutex
	v  bool
}

func (b *atomicBool) store(v bool) { b.mu.Lock(); defer b.mu.Unlock(); b.v = v }
func (b *atomicBool) load() bool   { b.mu.Lock(); defer b.mu.Unlock(); return b.v }
