```go
package cli

import (
	"fmt"
	"regexp"
	"strings"
	"time"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/bubbles/spinner"
	"github.com/charmbracelet/lipgloss"
)

// reviewTUIModel renders the multi-agent status table.
type reviewTUIModel struct {
	tasks      []MultiAgentTask
	rows       []rowState
	spinner    spinner.Model
	startTime  time.Time
	termWidth  int
	allDone    bool
	cancelling bool
}

type rowState struct {
	name     string
	status   AgentRunStatus
	duration time.Duration
	tokens   int
	preview  string
	exitCode int
}

// Messages.
type agentStateMsg struct {
	Name     string
	Status   AgentRunStatus
	Duration time.Duration
	ExitCode int
	Tokens   int
}

type agentPreviewMsg struct {
	Name string
	Line string
}

type cancelMsg struct{}

type tickMsg time.Time

var ansiRe = regexp.MustCompile(`\x1b\[[0-9;]*[a-zA-Z]`)

func stripANSI(s string) string {
	return ansiRe.ReplaceAllString(s, "")
}

func newReviewTUIModel(tasks []MultiAgentTask) reviewTUIModel {
	rows := make([]rowState, len(tasks))
	for i, t := range tasks {
		rows[i] = rowState{name: t.Name, status: AgentRunQueued}
	}
	sp := spinner.New()
	sp.Spinner = spinner.Dot
	return reviewTUIModel{
		tasks:     tasks,
		rows:      rows,
		spinner:   sp,
		startTime: time.Now(),
		termWidth: 80,
	}
}

func (m reviewTUIModel) Init() tea.Cmd {
	return tea.Batch(m.spinner.Tick, tickEvery())
}

func tickEvery() tea.Cmd {
	return tea.Tick(100*time.Millisecond, func(t time.Time) tea.Msg { return tickMsg(t) })
}

func (m reviewTUIModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.termWidth = msg.Width
	case agentStateMsg:
		for i, r := range m.rows {
			if r.name == msg.Name {
				m.rows[i].status = msg.Status
				if msg.Duration > 0 {
					m.rows[i].duration = msg.Duration
				}
				m.rows[i].exitCode = msg.ExitCode
				m.rows[i].tokens = msg.Tokens
				break
			}
		}
		if m.allRowsTerminal() {
			m.allDone = true
			return m, tea.Quit
		}
	case agentPreviewMsg:
		for i, r := range m.rows {
			if r.name == msg.Name {
				line := stripANSI(msg.Line)
				// Truncate to terminal width minus row prefix (~18 chars).
				maxLine := m.termWidth - 18
				if maxLine < 20 {
					maxLine = 20
				}
				if len(line) > maxLine {
					line = line[:maxLine-1] + "…"
				}
				m.rows[i].preview = line
				break
			}
		}
	case cancelMsg:
		m.cancelling = true
	case tickMsg:
		// Bump durations for running rows.
		now := time.Now()
		for i, r := range m.rows {
			if r.status == AgentRunRunning {
				m.rows[i].duration = now.Sub(m.startTime)
			}
		}
		return m, tickEvery()
	case spinner.TickMsg:
		var cmd tea.Cmd
		m.spinner, cmd = m.spinner.Update(msg)
		return m, cmd
	}
	return m, nil
}

func (m reviewTUIModel) View() string {
	var sb strings.Builder
	sb.WriteString("Running ")
	sb.WriteString(fmt.Sprintf("%d agents — Ctrl+C to cancel all\n\n", len(m.rows)))
	sb.WriteString(strings.Repeat("─", 44) + "\n")
	for _, r := range m.rows {
		icon := rowIcon(r.status, m.spinner.View())
		status := statusString(r.status)
		dur := formatDuration(r.duration)
		tok := "—"
		if r.tokens > 0 {
			tok = fmt.Sprintf("%dk", r.tokens/1000)
		}
		line := fmt.Sprintf("  %s  %-15s %-10s %7s  %5s\n",
			icon, r.name, status, dur, tok)
		sb.WriteString(line)
		if r.preview != "" {
			sb.WriteString("       ")
			sb.WriteString(lipgloss.NewStyle().Faint(true).Render("… " + r.preview))
			sb.WriteString("\n")
		}
	}
	sb.WriteString(strings.Repeat("─", 44) + "\n")
	completed := 0
	for _, r := range m.rows {
		if r.status == AgentRunDone || r.status == AgentRunFailed || r.status == AgentRunCancelled {
			completed++
		}
	}
	sb.WriteString(fmt.Sprintf("%d of %d complete\n", completed, len(m.rows)))
	return sb.String()
}

func (m *reviewTUIModel) allRowsTerminal() bool {
	for _, r := range m.rows {
		if r.status == AgentRunQueued || r.status == AgentRunRunning {
			return false
		}
	}
	return true
}

func rowIcon(status AgentRunStatus, spin string) string {
	switch status {
	case AgentRunDone:
		return "✓"
	case AgentRunFailed:
		return "✗"
	case AgentRunCancelled:
		return "⊘"
	case AgentRunRunning:
		return spin
	default:
		return " "
	}
}

func statusString(status AgentRunStatus) string {
	switch status {
	case AgentRunDone:
		return "done"
	case AgentRunFailed:
		return "failed"
	case AgentRunCancelled:
		return "cancelled"
	case AgentRunRunning:
		return "running"
	default:
		return "queued"
	}
}

func formatDuration(d time.Duration) string {
	if d == 0 {
		return "—"
	}
	s := int(d.Seconds())
	if s < 60 {
		return fmt.Sprintf("%ds", s)
	}
	return fmt.Sprintf("%dm %ds", s/60, s%60)
}
```

