// extractFinalMessage pulls the agent's last narrative response from the
// cleaned (post-filter) output. Per-agent heuristics because different
// agents delimit responses differently. Unknown agents pass through.
func extractFinalMessage(agentName, cleaned string) string {
	switch agentName {
	case "codex":
		return extractCodexFinal(cleaned)
	default:
		// Claude --print output is already just the final message.
		// Gemini: no observed format; pass through until we add a handler.
		return cleaned
	}
}

// extractCodexFinal finds text between the last line matching `^codex$`
// and the `tokens used` marker. Falls back to full cleaned output if
// markers not found (defensive — format may drift in future codex
// versions; no silent data loss).
func extractCodexFinal(cleaned string) string {
	lines := strings.Split(cleaned, "\n")
	lastCodexMarker := -1
	tokensUsedIdx := -1
	for i, line := range lines {
		if strings.TrimSpace(line) == "codex" {
			lastCodexMarker = i
		}
		if strings.HasPrefix(line, "tokens used") && lastCodexMarker != -1 {
			tokensUsedIdx = i
			break
		}
	}
	if lastCodexMarker == -1 || tokensUsedIdx == -1 {
		return cleaned
	}
	return strings.Join(lines[lastCodexMarker+1:tokensUsedIdx], "\n")
}
```

